window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ca8f8d7a73ff4d22"]={"versions": [{"id": "FIG-ca8f8d7a73ff4d22", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses der Funktion <code>E2E_P06Forward()</code> innerhalb des AUTOSAR E2E-Protokolls (Profile 6). Das Diagramm beschreibt den Teilschritt „Write Counter“ zur Anpassung und Serialisierung des E2E-Sequenzzählers bei Weiterleitungsoperationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Funktion / Kontext</strong>: <code>E2E_P06Forward()</code>\n</li><li><strong>Zustands- und Konfigurationsstrukturen</strong>:\n<ul class=\"fig-list\"><li><code>State-&gt;Counter</code>: 1-Byte-Zähler vom Typ <code>uint8</code>\n</li><li><code>Config-&gt;MaxDeltaCounter</code>: Maximal zulässige Zählerdifferenz aus der E2E-Profil-6-Konfiguration\n</li><li><code>ForwardStatus</code>: Statusübergabewert der Weiterleitung (<code>E2E_P_REPEATED</code>, <code>E2E_P_WRONGSEQUENCE</code> oder andere Zustände im else-Zweig)\n</li></ul>\n</li><li><strong>Nutzdaten-Array</strong>:\n<ul class=\"fig-list\"><li><code>Data[]</code>: Byte-Array der Nutzdaten; Zielposition ist <code>Data[Offset+4]</code> im Big-Endian-Format\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Start</strong>: Eintritt über den initialen Pseudozustand in den Schritt „Write Counter“.\n</li><li><strong>Prüfung Status REPEATED</strong>: Verzweigung an der ersten Decision Node anhand von <code>if ForwardStatus == E2E_P_REPEATED</code>:\n<ul class=\"fig-list\"><li><code>[TRUE]</code>: Dekrementieren des Zählers (<code>State-&gt;Counter--</code>). Anschließend Zusammenführung.\n</li><li><code>[FALSE]</code>: Weiterleitung zur nächsten Verzweigung.\n</li></ul>\n</li><li><strong>Prüfung Status WRONGSEQUENCE</strong>: Verzweigung anhand von <code>if ForwardStatus == E2E_P_WRONGSEQUENCE</code>:\n<ul class=\"fig-list\"><li><code>[TRUE]</code>: Setzen des Zählers auf <code>State-&gt;Counter = State-&gt;Counter + Config-&gt;MaxDeltaCounter</code>. Anschließend Zusammenführung.\n</li><li><code>[FALSE]</code>: Verzweigung zum <code>else</code>-Zweig, in dem der Zähler unverändert bleibt.\n</li></ul>\n</li><li><strong>Zusammenführung</strong>: Zusammenführung der drei Pfade in einer Merge Node.\n</li><li><strong>Serialisierung</strong>: Ausführen der Aktion <code>Copy 1-byte State-&gt;Counter on byte Data[Offset+4] in Big Endian order</code>.\n</li><li><strong>Ende</strong>: Übergang zum Aktivitätsendzustand.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Vorgabe</strong>: Gemäß Anforderung <code>[PRS_E2E_00624]</code> ist das Verhalten des Schritts „Write Counter“ für Profil 6 verbindlich umzusetzen.\n</li><li><strong>Arithmetik &amp; Überlauf</strong>: Der Datentyp von <code>State-&gt;Counter</code> ist <code>uint8</code>. Es gilt modulo 256 Arithmetik: Auf den Wert <code>0xFF</code> folgt <code>0x00</code>, bzw. Unterlauf bei Dekrement von <code>0x00</code> auf <code>0xFF</code>.\n</li><li><strong>Speicherlayout</strong>: Die Ablage des Zählers erfolgt fest an Byte-Position <code>Data[Offset+4]</code> in Big-Endian-Byte-Reihenfolge.\n</li><li><strong>Zählerkompensation</strong>: Bei wiederholten Nachrichten (<code>E2E_P_REPEATED</code>) wird der Zähler dekrementiert, bei Sequenzfehlern (<code>E2E_P_WRONGSEQUENCE</code>) um <code>MaxDeltaCounter</code> erhöht, um im nachfolgenden Übertragungsabschnitt den erwarteten Zählerstand des Empfängers zu synchronisieren.\n</li></ul>"}, {"id": "FIG-480ec08196936a59", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses der Funktion <code>E2E_P06Forward()</code> innerhalb des AUTOSAR E2E-Protokolls (Profile 6). Das Diagramm beschreibt den Teilschritt „Write Counter“ zur Anpassung und Serialisierung des E2E-Sequenzzählers bei Weiterleitungsoperationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Funktion / Kontext</strong>: <code>E2E_P06Forward()</code>\n</li><li><strong>Zustands- und Konfigurationsstrukturen</strong>:\n<ul class=\"fig-list\"><li><code>State-&gt;Counter</code>: 1-Byte-Zähler vom Typ <code>uint8</code>\n</li><li><code>Config-&gt;MaxDeltaCounter</code>: Maximal zulässige Zählerdifferenz aus der E2E-Profil-6-Konfiguration\n</li><li><code>ForwardStatus</code>: Statusübergabewert der Weiterleitung (<code>E2E_P_REPEATED</code>, <code>E2E_P_WRONGSEQUENCE</code> oder andere Zustände im else-Zweig)\n</li></ul>\n</li><li><strong>Nutzdaten-Array</strong>:\n<ul class=\"fig-list\"><li><code>Data[]</code>: Byte-Array der Nutzdaten; Zielposition ist <code>Data[Offset+4]</code> im Big-Endian-Format\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Start</strong>: Eintritt über den initialen Pseudozustand in den Schritt „Write Counter“.\n</li><li><strong>Prüfung Status REPEATED</strong>: Verzweigung an der ersten Decision Node anhand von <code>if ForwardStatus == E2E_P_REPEATED</code>:\n<ul class=\"fig-list\"><li><code>[TRUE]</code>: Dekrementieren des Zählers (<code>State-&gt;Counter--</code>). Anschließend Zusammenführung.\n</li><li><code>[FALSE]</code>: Weiterleitung zur nächsten Verzweigung.\n</li></ul>\n</li><li><strong>Prüfung Status WRONGSEQUENCE</strong>: Verzweigung anhand von <code>if ForwardStatus == E2E_P_WRONGSEQUENCE</code>:\n<ul class=\"fig-list\"><li><code>[TRUE]</code>: Setzen des Zählers auf <code>State-&gt;Counter = State-&gt;Counter + Config-&gt;MaxDeltaCounter</code>. Anschließend Zusammenführung.\n</li><li><code>[FALSE]</code>: Verzweigung zum <code>else</code>-Zweig, in dem der Zähler unverändert bleibt.\n</li></ul>\n</li><li><strong>Zusammenführung</strong>: Zusammenführung der drei Pfade in einer Merge Node.\n</li><li><strong>Serialisierung</strong>: Ausführen der Aktion <code>Copy 1-byte State-&gt;Counter on byte Data[Offset+4] in Big Endian order</code>.\n</li><li><strong>Ende</strong>: Übergang zum Aktivitätsendzustand.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Vorgabe</strong>: Gemäß Anforderung <code>[PRS_E2E_00624]</code> ist das Verhalten des Schritts „Write Counter“ für Profil 6 verbindlich umzusetzen.\n</li><li><strong>Arithmetik &amp; Überlauf</strong>: Der Datentyp von <code>State-&gt;Counter</code> ist <code>uint8</code>. Es gilt modulo 256 Arithmetik: Auf den Wert <code>0xFF</code> folgt <code>0x00</code>, bzw. Unterlauf bei Dekrement von <code>0x00</code> auf <code>0xFF</code>.\n</li><li><strong>Speicherlayout</strong>: Die Ablage des Zählers erfolgt fest an Byte-Position <code>Data[Offset+4]</code> in Big-Endian-Byte-Reihenfolge.\n</li><li><strong>Zählerkompensation</strong>: Bei wiederholten Nachrichten (<code>E2E_P_REPEATED</code>) wird der Zähler dekrementiert, bei Sequenzfehlern (<code>E2E_P_WRONGSEQUENCE</code>) um <code>MaxDeltaCounter</code> erhöht, um im nachfolgenden Übertragungsabschnitt den erwarteten Zählerstand des Empfängers zu synchronisieren.\n</li></ul>"}], "trans": [{"from": "FIG-ca8f8d7a73ff4d22", "to": "FIG-480ec08196936a59", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
